package test;

import org.eclipse.jface.viewers.StructuredViewer;
import org.eclipse.jface.viewers.Viewer;
import org.eclipse.jface.viewers.ViewerSorter;

public class NegativeTestClass {
    // This class still extends the deprecated ViewerSorter
    private final class LegacySorter extends ViewerSorter {
        @Override
        public int compare(Viewer viewer, Object e1, Object e2) {
            return 0;
        }
    }

    public void configureViewer(StructuredViewer result) {
        LegacySorter sorter = new LegacySorter();
        // This call should NOT be transformed because 'sorter' is not an instance of ViewerComparator
        result.setSorter(sorter);
    }
}
